"""
Adaptive Rejection Sampling (ARS) implementation based on Gilks & Wild (1992).
"""

import numpy as np
from scipy import stats


def ars(logpdf, n_samples, domain=(-np.inf, np.inf), initial_points=None, 
        n_initial=4, check_log_concavity=True):
    """
    Adaptive Rejection Sampler for log-concave distributions.

    Parameters
    ----------
    logpdf : callable
        Log probability density function. Must be log-concave.
    n_samples : int
        Number of samples to draw.
    domain : tuple
        Domain bounds (lower, upper). Default is (-inf, inf).
    initial_points : array-like, optional
        Initial x values for the envelope. If None, auto-generate.
    n_initial : int
        Number of initial points if not provided (default 4).
    check_log_concavity : bool
        Whether to check for log-concavity violations (default True).

    Returns
    -------
    samples : ndarray
        Array of samples from the target distribution.
    """

    # Input validation
    if not isinstance(n_samples, int) or n_samples <= 0:
        raise ValueError(f"n_samples must be a positive integer, got {n_samples}")

    if not callable(logpdf):
        raise ValueError("logpdf must be callable")

    if domain[0] >= domain[1]:
        raise ValueError(f"Invalid domain: lower={domain[0]} >= upper={domain[1]}")

    sampler = _AdaptiveRejectionSamplerImpl(
        logpdf, domain, initial_points, n_initial, check_log_concavity
    )
    return sampler.sample(n_samples)


class _AdaptiveRejectionSamplerImpl:
    """Internal implementation of ARS."""

    def __init__(self, logpdf, domain, initial_points, n_initial, check_log_concavity):
        self.logpdf = logpdf
        self.lower, self.upper = domain
        self.check_log_concavity = check_log_concavity

        # Initialize hull points
        if initial_points is not None:
            self.x = np.sort(np.asarray(initial_points, dtype=float))
        else:
            self.x = self._generate_initial_points(n_initial)

        # Evaluate logpdf at hull points
        self.logpdf_vals = self.logpdf(self.x)

        # Compute derivatives
        self._compute_derivatives()

    def _generate_initial_points(self, n_initial):
        """Generate initial hull points."""
        if self.lower == -np.inf and self.upper == np.inf:
            return np.linspace(-1.5, 1.5, n_initial)
        elif self.lower == -np.inf:
            return np.linspace(self.upper - 3, self.upper - 0.5, n_initial)
        elif self.upper == np.inf:
            return np.linspace(self.lower + 0.5, self.lower + 3, n_initial)
        else:
            return np.linspace(self.lower + 0.1*(self.upper - self.lower),
                              self.upper - 0.1*(self.upper - self.lower), n_initial)

    def _compute_derivatives(self):
        """Compute log-derivatives via finite differences."""
        self.logpdf_derivs = np.zeros_like(self.x)
        eps = 1e-7

        for i, xi in enumerate(self.x):
            if xi + eps <= self.upper and xi - eps >= self.lower:
                df = (self.logpdf(xi + eps) - self.logpdf(xi - eps)) / (2 * eps)
            elif xi + eps > self.upper:
                df = (self.logpdf(xi) - self.logpdf(xi - eps)) / eps
            else:
                df = (self.logpdf(xi + eps) - self.logpdf(xi)) / eps
            self.logpdf_derivs[i] = df

    def _tangent_line(self, x, i):
        """Tangent line at point i: h(x) + h'(x)(x - x_i)."""
        return self.logpdf_vals[i] + self.logpdf_derivs[i] * (x - self.x[i])

    def _find_intersections(self):
        """Find intersections of consecutive tangent lines."""
        intersections = []

        for i in range(len(self.x) - 1):
            x1, x2 = self.x[i], self.x[i+1]
            h1, h2 = self.logpdf_vals[i], self.logpdf_vals[i+1]
            hp1, hp2 = self.logpdf_derivs[i], self.logpdf_derivs[i+1]

            # Solve: h1 + hp1*(x-x1) = h2 + hp2*(x-x2)
            denom = hp1 - hp2
