                x_int = (x1 + x2) / 2
            else:
                x_int = (h2 - h1 + hp1*x1 - hp2*x2) / denom

            x_int = np.clip(x_int, x1, x2)
            intersections.append(x_int)

        return np.array(intersections)

    def _upper_hull(self, x):
        """Evaluate upper hull at x."""
        if x < self.x[0] or x > self.x[-1]:
            return -np.inf

